    // MARK: - Media

    /// File > Add Media… (⇧⌘I). The probe is asynchronous and the whole
        // nothing for a case it cannot reach.
        if view.window?.attachedSheet != nil { return false }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard let scalar = event.charactersIgnoringModifiers?.unicodeScalars.first else {
            return false
        }
        guard EditorKey.isBare(flags, scalar: scalar.value) else { return false }
        let shift = flags.contains(.shift)
        switch scalar.value {
        case UInt32(NSLeftArrowFunctionKey):
            stepFrames(shift ? -10 : -1)
        case UInt32(NSRightArrowFunctionKey):
            stepFrames(shift ? 10 : 1)
        case UInt32(NSUpArrowFunctionKey):
            previousEditPoint(nil)
        case UInt32(NSDownArrowFunctionKey):
            nextEditPoint(nil)
        case UInt32(NSHomeFunctionKey):
            goToStart(nil)
        case UInt32(NSEndFunctionKey):
            goToEnd(nil)
        case 27: return deselectActionCommand()
        default:
            return handleEditorCharacter(Character(scalar), shift: shift)
        }
        return true
    }

    /// Compared as a lowercased STRING, not a `Character`: lowercasing is not
    /// one-to-one in every locale (a Turkish "İ" becomes two scalars), and
    /// `Character(String)` traps on anything but exactly one.
    private func handleEditorCharacter(_ character: Character, shift: Bool) -> Bool {
        switch character.lowercased() {
        case " ":
            playPause(nil)
        case "j":
            shuttle(forward: false)
        case "k":
            playback.pause()
        case "l":
            shuttle(forward: true)
        case "i":
            setInPoint(nil)
        case "o":
            setOutPoint(nil)
        case "n":
            toggleSnapping(nil)
        case "m":
            addMarker(nil)
        case "w":
            trimStartToPlayhead(nil)
        case "e":
            trimEndToPlayhead(nil)
        case "t":
            addTextClip(nil)
        case "c":
            toggleCropMode(nil)
        case "z" where shift:
            fitTimeline(nil)
        // Bare Z arms the canvas region mode (road map 2's phase 3b, spec §9),
        // and it must stay BELOW the ⇧Z case: a `switch` matches in source
        // order, so a bare "z" above it would swallow Fit Timeline silently.
        // The command itself toggles, so Z is also the way back out
        // (EditorViewController+ZoomRegion.swift).
        case "z":
            zoomToRegion(nil)
        // ⇧ is still applied to `charactersIgnoringModifiers`, so ⇧, arrives
        // as "<" on a US layout — both spellings mean the same nudge.
        case ",", "<":
            nudgeSelection(frames: shift ? -10 : -1)
        case ".", ">":
            nudgeSelection(frames: shift ? 10 : 1)
        default:
            return false
        }
        return true
    }

    private func stepFrames(_ count: Int) {
        guard let document = document else { return }
        playback.stepFrames(count, fps: document.editedProject.snapshot.canvas.fps)
        document.playhead = playback.currentTime
        refreshTimecode()
    }

    // MARK: - Clip, track and marker actions
    //
    // One-line forwards into `EditorViewController+Timeline.swift`, which owns
    // the bodies (app/CLAUDE.md: this file stays wiring).

    @objc func splitAtPlayhead(_ sender: Any?) { splitAtPlayheadCommand() }
    @objc func trimStartToPlayhead(_ sender: Any?) { trimToPlayhead(.start) }
    @objc func trimEndToPlayhead(_ sender: Any?) { trimToPlayhead(.end) }
    @objc func deleteClips(_ sender: Any?) { deleteSelection() }
    @objc func rippleDeleteClips(_ sender: Any?) { rippleDeleteSelection() }
    @objc func duplicateClips(_ sender: Any?) { duplicateSelection() }

import AVFoundation
import AppKit

/// View ▸ Preview Quality ▸ Full / Half / Quarter (road map 2's phase 8a) — the
/// fraction of the canvas the PLAYER's video composition renders at, and
/// nothing else.
///
/// **What it buys, and what it does not.** The compositor's fragment work is
/// per DESTINATION pixel, so Half quarters it and Quarter divides it by
/// sixteen; the `AVPlayerLayer` then upsamples what it is handed, which is what
/// `.resizeAspect` was already doing to fit the canvas into the pane. Three
/// costs are untouched, and they are named here so nobody later reads a
/// smaller-than-expected saving as a bug:
///
/// · **The shadow passes.** `MetalRenderer.shadowSilhouette` allocates its
///   mask/blur pair at the RECIPE CANVAS's size (`Compositor.swift`), not at
///   the destination's, because the silhouette is drawn in canvas coordinates
///   and blurred with a σ derived from canvas pixels. A shadowed layer costs
///   exactly what it always did at every quality.
/// · **Decoding.** `Playback.finishRebuild` sets
///   `AVPlayerItem.preferredMaximumResolution` to the canvas size, and this
///   setting deliberately leaves it there: it is the DECODE ceiling, and
///   lowering it would degrade the picture by more than the resample the menu
///   promises — a paused Half frame is meant to be the Full frame through one
///   scaler, not a different frame.
/// · **The audio path**, which has no render size at all.
///
/// **It is the player's alone, by construction rather than by testing.** There
/// is exactly one builder of the video composition in the app
/// (`CompositionBuilder.build`, from an `AVVideoComposition.Configuration` it
/// keeps on `BuiltComposition.videoConfiguration`), and it is shared by the
/// preview, both export passes and the offline one-frame render. Rather than
/// give that function an argument every caller would have to pass correctly,
/// `Playback.previewComposition` copies the configuration it was handed,
/// overrides `renderSize` on the COPY and builds from that —
/// `ExportWriter.videoComposition(_:settings:)`'s shape exactly, which does
/// the same to `frameDuration` for the export sheet's frame-rate popup. The
/// export and `render_frame` paths are therefore not merely unchanged but
/// UNREACHABLE from this setting: they never see the copy.
///
/// **No MCP mirror is owed and none may be added.** The parity rule (spec §7.9)
/// is that every user-visible EDIT gets a tool; this edits nothing, and there
/// is nothing an agent could observe if it did — `render_frame` and `export`
/// ignore it by the paragraph above. Phase 7e's export queue is the precedent
/// for a feature that correctly earns none.
enum PreviewQuality: Int, CaseIterable {
    case full = 0
    case half = 1
    case quarter = 2

    /// The submenu's rows, in order. The raw value IS the menu tag, so a
    /// fourth quality goes at the END of this list.
    var title: String {
        switch self {
        case .full: return "Full"
        case .half: return "Half"
        case .quarter: return "Quarter"
        }
    }

    /// What the canvas is divided by — the fraction the row's name promises,
    /// before the aspect rule below has its say.
    var divisor: Int {
        switch self {
        case .full: return 1
        case .half: return 2
        case .quarter: return 4
        }
    }

    /// View state, so `UserDefaults` and not the project (spec §5.2's last
    /// bullet), and pinned by the offscreen harness like every other key the
    /// app reads (`tools/proof/harness/main.swift`).
    static let defaultsKey = "FrameJobPreviewQuality"

    /// What a new `Playback` starts at. An absent key — and a stored number
    /// outside the three cases, which is what a downgrade after a future
    /// fourth row would leave behind — both read as Full, because Full is the
    /// only value that cannot surprise somebody who does not know the setting
    /// exists.
    static func stored() -> PreviewQuality {
        let defaults = UserDefaults.standard
        guard defaults.object(forKey: defaultsKey) != nil,
            let quality = PreviewQuality(rawValue: defaults.integer(forKey: defaultsKey))
        else { return .full }
        return quality
    }

    func store() {
        UserDefaults.standard.set(rawValue, forKey: PreviewQuality.defaultsKey)
    }

    /// The render size for `canvas` at this quality — **always at the canvas's
    /// EXACT aspect ratio**, which is the subtle half of this feature.
    ///
    /// `PreviewCanvasView` maps every mouse point and every drag handle through
    /// `AVPlayerLayer.videoRect` under `.resizeAspect` (`videoRectInView`,
    /// `canvasScale`, spec §4.2 and §11). `videoRect` is the aspect of the
    /// BUFFER the layer is showing, not of the canvas — so a render size whose
    /// aspect differs from the canvas's, even slightly, letterboxes inside the
    /// layer and moves every handle in the frame. Measured, because it is
    /// cheap to measure and expensive to be wrong about: a 640 × 360 timeline
    /// rendered at 501 × 333 comes back with `videoRect` at aspect 1.504505
    /// where the canvas is 1.777778, and the compositor draws the whole canvas
    /// into that box, so the picture is stretched as well.
    ///
    /// So the size must be an exact multiple of the canvas's REDUCED ratio.
    /// With `g = gcd(width, height)`, every exactly-proportional size is
    /// `m · (width/g, height/g)` for some whole `m ≤ g`, and this answers with
    /// `m = ceil(g / divisor)`:
------
    /// this — the place a person naturally starts a band — and a press here
    /// once answered `.none` and did nothing. It names no row, so a
    /// double-click here closes no gap.
    case outside
    /// Nothing: the header column under the last lane, or a content view
    /// with no owner.
    case none
}

// MARK: - Snapping

/// Spec §4.4's snapping, as one value a gesture can consult.
///
/// Candidates are the core's (`ReelProject.snapCandidates(excluding:)` —
/// every other clip's edges and the markers) plus the playhead and the
/// in/out points, which the core does not know about because they are view
/// state. `enabled` folds together the N toggle and the ⌘ suppression, so a
/// session never has to look at modifier flags itself.
struct TimelineSnapper {
    let fps: Fps
    let candidates: [Ticks]
    /// Radius in ticks — `TimelineLayout.snapThreshold`, i.e. 8 points.
    let threshold: Ticks
    let enabled: Bool

    /// The time to actually use, and the guide to draw (nil when nothing
    /// was snapped). A candidate is already on the frame grid, so only the
    /// unsnapped case needs `snapToFrame` — but every tick that reaches an
    /// op leaves here on the grid either way (spec §6).
    func resolve(_ time: Ticks) -> (time: Ticks, guide: Ticks?) {
        guard enabled else { return (ReelTime.snapToFrame(time, fps: fps), nil) }
        let (resolved, snapped) = ReelSnap.resolve(candidates, time, threshold: threshold)
        if snapped { return (resolved, resolved) }
        return (ReelTime.snapToFrame(time, fps: fps), nil)
    }

    /// The candidate list for a gesture that must not snap to the very clips
    /// it is moving. `core` comes from `snapCandidates(excluding:)`.
    static func candidates(
        core: [Ticks], playhead: Ticks, range: (start: Ticks, end: Ticks)?
    ) -> [Ticks] {
        var all = core
        all.append(playhead)
        if let range = range {
            all.append(range.start)
            all.append(range.end)
        }
        return Array(Set(all)).sorted()
    }
}

// MARK: - Clip drag

------
    func visibleRange(_ rect: CGRect) -> (start: Ticks, end: Ticks) {
        let start = max(time(atX: rect.minX), 0)
        let end = max(time(atX: rect.maxX), start)
        return (start, end)
    }

    // MARK: - Ruler

    /// Tick spacing for the ruler, adaptive as spec §4.4 asks: frames while
    /// they are far enough apart to see, then seconds, 10 s and minutes.
    /// Minors need 6 pt of air, labelled majors 68 pt (a "MM:SS:FF" in 9 pt
    /// mono is about 48).
    func rulerSteps() -> (minor: Ticks, major: Ticks) {
        let ladder = Self.ladder(frame: canvas.fps.frameDuration)
        let minor = ladder.first { width(of: $0) >= 6 } ?? ladder[ladder.count - 1]
        let major = ladder.first { width(of: $0) >= 68 && $0 >= minor } ?? minor
        return (minor, max(major, minor))
    }

    /// Frames → seconds → minutes → hours, deduplicated and sorted. A
    /// degenerate frame duration (a 0-denominator rate) drops the frame rungs
    /// rather than dividing by zero.
    static func ladder(frame: Ticks) -> [Ticks] {
        let second = ReelTime.perSecond
        var steps: [Ticks] = []
        if frame > 0 {
            steps += [frame, frame * 2, frame * 5, frame * 10]
        }
        steps += [
            second, second * 2, second * 5, second * 10, second * 15, second * 30,
            second * 60, second * 120, second * 300, second * 600, second * 900,
            second * 1800, second * 3600,
        ]
        return Array(Set(steps.filter { $0 > 0 })).sorted()
    }

    /// A ruler label. Spelling is `ReelTime.format`'s — the core's — so the
    /// ruler, the toolbar and the agent never disagree about a time; the only
    /// liberty taken is dropping a leading `00:` hour when the whole project
    /// is under an hour, because an 11-glyph label does not fit at 68 pt.
    func rulerLabel(_ time: Ticks) -> String {
        let text = ReelTime.format(time, fps: canvas.fps, frames: canvas.timecodeFrames)
        guard duration < ReelTime.perSecond * 3600, text.hasPrefix("00:") else { return text }
        return String(text.dropFirst(3))
    }
}
